'use client';

import { useId, useState, type ReactNode } from 'react';
import './peel-corner-card.css';

export interface PeelCornerCardProps {
  children: ReactNode;
  /** The secondary label under the corner. It stays readable to assistive tech. */
  hidden: ReactNode;
  /** Accessible name for the corner toggle. */
  toggleLabel: string;
  className?: string;
}

/**
 * A folded corner lifts to show a small label printed underneath. The corner
 * is a real toggle button with a large tap target.
 */
export function PeelCornerCard({
  children,
  hidden,
  toggleLabel,
  className = '',
}: PeelCornerCardProps) {
  const [open, setOpen] = useState(false);
  const id = useId();
  return (
    <div className={`mg-peel ${className}`} data-open={open}>
      <div className='mg-peel__under' id={id}>
        {hidden}
      </div>
      <div className='mg-peel__face'>{children}</div>
      <span className='mg-peel__flap' aria-hidden='true' />
      <button
        type='button'
        className='mg-peel__toggle'
        aria-expanded={open}
        aria-controls={id}
        aria-label={toggleLabel}
        onClick={() => setOpen((value) => !value)}
      />
    </div>
  );
}

.mg-peel {
  --mg-fold: 34px;
  position: relative;
  min-height: 150px;
  border-radius: 14px;
  color: var(--mg-text, #ffffff);
}

.mg-peel[data-open='true'] {
  --mg-fold: 104px;
}

.mg-peel__under {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  padding: 14px;
  border-radius: 14px;
  background: var(--mg-raised, #262626);
  color: var(--mg-accent-text, #8aa8ff);
  font-weight: 700;
  text-align: right;
}

/* The face loses its bottom-right triangle as the corner folds back. */
.mg-peel__face {
  position: relative;
  min-height: inherit;
  padding: 20px;
  border: 1px solid var(--mg-line, #303030);
  border-radius: 14px;
  background: #121212;
  clip-path: polygon(
    0 0,
    100% 0,
    100% calc(100% - var(--mg-fold)),
    calc(100% - var(--mg-fold)) 100%,
    0 100%
  );
  transition: clip-path 420ms cubic-bezier(0.3, 1.3, 0.5, 1);
}

/* The folded-over flap: the mirror triangle on the near side of the crease. */
.mg-peel__flap {
  position: absolute;
  right: 0;
  bottom: 0;
  width: var(--mg-fold);
  height: var(--mg-fold);
  background: linear-gradient(135deg, #303030 0%, #121212 50%, transparent 50%);
  border-radius: 0 0 14px 0;
  filter: drop-shadow(-3px -3px 4px rgba(0, 0, 0, 0.18));
  pointer-events: none;
  transition:
    width 420ms cubic-bezier(0.3, 1.3, 0.5, 1),
    height 420ms cubic-bezier(0.3, 1.3, 0.5, 1);
}

.mg-peel__toggle {
  position: absolute;
  right: 0;
  bottom: 0;
  width: max(48px, var(--mg-fold));
  height: max(48px, var(--mg-fold));
  border: 0;
  border-radius: 0 0 14px 0;
  background: none;
  cursor: pointer;
}

.mg-peel__toggle:focus-visible {
  outline: 3px solid var(--mg-accent-text, #648aff);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  .mg-peel__face,
  .mg-peel__flap {
    transition: none;
  }
}
